import { createClient } from 'npm:@supabase/supabase-js@2';

// ---- prices.js ----
// Card value, exactly as the app computes it (app.js: pickPrice, tcpMarket, priceCheck, entryValue, wishDeal).
// Kept as a copy so the daily server job needs no code fetched at run time; tests/push_t.py checks that both give
// the same results on the same cards. If the app's price logic changes, change it here too.

function pickPrice(pricing, variant, hasNormal) {
  const cm = pricing?.cardmarket;
  if (!cm) return null;
  const useHolo = (variant === 'reverse' || ((variant === 'holo' || variant === 'foil') && hasNormal)) && (cm['trend-holo'] > 0 || cm['avg7-holo'] > 0);
  const f = k => { const v = cm[useHolo ? k + '-holo' : k]; return v == null || v === 0 ? null : v; };
  const p = { trend: f('trend'), low: f('low'), avg1: f('avg1'), avg7: f('avg7'), avg30: f('avg30'), updated: cm.updated };
  const vals = [p.trend, p.avg1, p.avg7, p.avg30].filter(v => v > 0).sort((a, b) => a - b);
  p.value = vals.length ? (vals.length % 2 ? vals[(vals.length - 1) / 2] : (vals[vals.length / 2 - 1] + vals[vals.length / 2]) / 2) : p.low;
  if (p.value != null) p.value = Math.round(p.value * 100) / 100;
  return p.value == null ? null : p;
}

function tcpMarket(tcp, variant) {
  if (!tcp) return null;
  const order = { holo: ['holofoil', 'holo'], foil: ['holofoil', 'foil'], reverse: ['reverse-holofoil', 'reverseHolofoil', 'reverse'], normal: ['normal'] }[variant] || ['normal'];
  const pick = k => { const v = tcp[k]; return v && typeof v === 'object' ? (v.marketPrice || v.midPrice || null) : null; };
  for (const k of order) { const v = pick(k); if (v) return v; }
  for (const k of Object.keys(tcp)) { const v = pick(k); if (v) return v; }
  return null;
}

const RAR_FLOORS = [[/special|spéciale|hyper|gold|dorée|mega.?hyper|ace spec/i, 3], [/illustration|ultra|secret|shiny|chromatique|full ?art|rainbow|arc-en-ciel/i, 0.8]];
function rarityFloor(r) { for (const [re, f] of RAR_FLOORS) if (re.test(r || '')) return f; return 0; }
const gameOf = id => { id = String(id || ''); return id.startsWith('mg:') ? 'mg' : id.startsWith('op:') ? 'op' : 'pk'; };

function priceCheck(e, usdEur) {
  const cm = e.price?.value; if (!(cm > 0)) return null;
  const floor = gameOf(e.cardId) === 'mg' ? (/numérotée|serialized/i.test(e.rarity || '') ? 20 : 0) : rarityFloor(e.rarity);
  const usd = tcpMarket(e.tcp, e.variant), tp = usd ? Math.round(usd * usdEur * 100) / 100 : null;
  const low = floor && cm < floor, far = tp && tp >= 2 && cm < tp / 5;
  if (!low && !far) return null;
  return { cm, floor, alt: tp && tp >= Math.max(floor, cm * 5, 1) ? tp : null };
}
const myValue = (mp, est) => mp.est > 0 && est > 0 ? Math.round(est * mp.v / mp.est * 100) / 100 : mp.v;
const tcpOnly = (e, usdEur) => { if (e.price?.value > 0) return null; const u = tcpMarket(e.tcp, e.variant); return u > 0 ? Math.round(u * usdEur * 100) / 100 : null; };
function entryValue(e, usdEur) {
  if (e.manual > 0) return e.manual;
  if (e.myPrice?.v > 0) return myValue(e.myPrice, e.price?.value);
  const chk = priceCheck(e, usdEur); if (chk) return chk.alt;
  return e.price?.value ?? tcpOnly(e, usdEur);
}

// Magic (Scryfall) and One Piece (OPTCG) answers turned into the same shape as TCGdex (prices part only, like mgToDetail / opToDetail)
function mgPricing(c, pc) {
  const p = pc.prices || {}, f = c.finishes || [];
  const hasN = f.length ? f.includes('nonfoil') : c.nonfoil !== false, hasF = f.length ? (f.includes('foil') || f.includes('etched')) : !!c.foil;
  const eur = +p.eur || null, eurF = +p.eur_foil || +p.eur_etched || null;
  return { variants: { normal: hasN, foil: hasF },
    pricing: { cardmarket: { trend: hasN ? eur : eurF, 'trend-holo': eurF, updated: new Date().toISOString() },
      tcgplayer: { normal: +p.usd ? { marketPrice: +p.usd } : null, holofoil: +(p.usd_foil || p.usd_etched) ? { marketPrice: +(p.usd_foil || p.usd_etched) } : null } } };
}
function opPricing(row) {
  const mp = row && row.market_price != null ? +row.market_price : null;
  return { variants: { normal: true }, pricing: { tcgplayer: { normal: mp > 0 ? { marketPrice: mp } : null } } };
}

// Today's value of a card: the stored entry with today's prices put in (as the app's refresh does), then the app's value rule.
// A source that answers without a price keeps the last known one (the app keeps it 14 days; one day here is enough).
function valueToday(e, detail, usdEur) {
  const p = detail ? pickPrice(detail.pricing, e.variant, detail.variants?.normal) : null;
  const tcp = detail?.pricing?.tcgplayer || null, tcpOk = !!tcp && Object.values(tcp).some(v => v);
  const e2 = { ...e, price: p || e.price, tcp: tcpOk ? tcp : e.tcp };
  return { value: entryValue(e2, usdEur), cm: e2.price?.value ?? null };
}

// Wishlist « good deal » (app.js wishDeal): today's value against the first known price of the card, at least dealPct % lower.
// The app needs two history points; today's price counts as one when the history doesn't have today yet.
function dealDrop(e, value, todayStr) {
  if (value == null) return null;
  const hist = Array.isArray(e.hist) ? e.hist : [];
  const h0 = hist.find(x => x && x.v > 0)?.v;
  const points = hist.length + (hist.length && hist[hist.length - 1].d === todayStr ? 0 : 1);
  return h0 && points > 1 ? (value - h0) / h0 * 100 : 0;
}
function alertHit(e, value) {
  const a = e.alert; if (!a || !(a.price > 0) || value == null) return false;
  return a.dir === 'below' ? value <= a.price : a.dir === 'above' ? value >= a.price : false;
}

// ---- webpush.js ----
// Web Push sending with the platform's own crypto (Web Crypto), no third-party package:
// payload encryption « aes128gcm » (RFC 8291 / RFC 8188) and the VAPID signature that identifies the sender (RFC 8292).
// Works the same in the Supabase function (Deno) and in the tests (Node).

const enc = new TextEncoder();
const b64u = {
  enc: buf => { let s = ''; for (const b of new Uint8Array(buf)) s += String.fromCharCode(b); return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, ''); },
  dec: str => { const s = atob(String(str).replace(/-/g, '+').replace(/_/g, '/') + '==='.slice((String(str).length + 3) % 4)); return Uint8Array.from(s, c => c.charCodeAt(0)); },
};
const cat = (...parts) => { const out = new Uint8Array(parts.reduce((n, p) => n + p.length, 0)); let o = 0; for (const p of parts) { out.set(p, o); o += p.length; } return out; };
async function hkdf(salt, ikm, info, len) {
  const k = await crypto.subtle.importKey('raw', ikm, 'HKDF', false, ['deriveBits']);
  return new Uint8Array(await crypto.subtle.deriveBits({ name: 'HKDF', hash: 'SHA-256', salt, info }, k, len * 8));
}

// VAPID keys: public = uncompressed P-256 point (65 bytes), private = its 32-byte scalar, both base64url
async function makeVapid() {
  const k = await crypto.subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  return { pub: b64u.enc(await crypto.subtle.exportKey('raw', k.publicKey)), priv: (await crypto.subtle.exportKey('jwk', k.privateKey)).d };
}
async function vapidKey(pub, priv) {
  const P = b64u.dec(pub);
  if (P.length !== 65 || P[0] !== 4) throw new Error('VAPID public key must be 65 bytes (uncompressed)');
  return crypto.subtle.importKey('jwk', { kty: 'EC', crv: 'P-256', x: b64u.enc(P.slice(1, 33)), y: b64u.enc(P.slice(33)), d: priv, ext: true }, { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
}
async function vapidAuth(endpoint, subject, pub, key, now = Date.now()) {
  const aud = new URL(endpoint).origin;
  const head = b64u.enc(enc.encode(JSON.stringify({ typ: 'JWT', alg: 'ES256' })));
  const body = b64u.enc(enc.encode(JSON.stringify({ aud, exp: Math.floor(now / 1000) + 12 * 3600, sub: subject })));
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, enc.encode(head + '.' + body));   // raw r||s = JOSE format
  return `vapid t=${head}.${body}.${b64u.enc(sig)}, k=${pub}`;
}

// Encrypts for one subscription (keys p256dh + auth given by the browser). Returns the request body.
async function encrypt(payload, p256dh, authSecret, salt = crypto.getRandomValues(new Uint8Array(16))) {
  const ua = b64u.dec(p256dh), auth = b64u.dec(authSecret);
  const uaKey = await crypto.subtle.importKey('raw', ua, { name: 'ECDH', namedCurve: 'P-256' }, false, []);
  const as = await crypto.subtle.generateKey({ name: 'ECDH', namedCurve: 'P-256' }, true, ['deriveBits']);
  const asPub = new Uint8Array(await crypto.subtle.exportKey('raw', as.publicKey));
  const secret = new Uint8Array(await crypto.subtle.deriveBits({ name: 'ECDH', public: uaKey }, as.privateKey, 256));
  const ikm = await hkdf(auth, secret, cat(enc.encode('WebPush: info\0'), ua, asPub), 32);
  const cek = await hkdf(salt, ikm, enc.encode('Content-Encoding: aes128gcm\0'), 16);
  const nonce = await hkdf(salt, ikm, enc.encode('Content-Encoding: nonce\0'), 12);
  const key = await crypto.subtle.importKey('raw', cek, 'AES-GCM', false, ['encrypt']);
  const data = cat(typeof payload === 'string' ? enc.encode(payload) : payload, new Uint8Array([2]));   // single record: delimiter 0x02, no padding
  const ct = new Uint8Array(await crypto.subtle.encrypt({ name: 'AES-GCM', iv: nonce }, key, data));
  const rs = new Uint8Array([0, 0, 16, 0]);   // record size 4096
  return cat(salt, rs, new Uint8Array([asPub.length]), asPub, ct);
}

// Sends one notification. Returns the HTTP status (201 = accepted; 404 / 410 = this subscription no longer exists).
async function sendPush(fetchFn, sub, payload, vapid, ttl = 12 * 3600) {
  const body = await encrypt(JSON.stringify(payload), sub.p256dh, sub.auth);
  const r = await fetchFn(sub.endpoint, { method: 'POST', body, headers: {
    TTL: String(ttl), Urgency: 'normal', 'Content-Encoding': 'aes128gcm', 'Content-Type': 'application/octet-stream',
    Authorization: await vapidAuth(sub.endpoint, vapid.subject, vapid.pub, vapid.key) } });
  return r.status;
}

// ---- core.js ----
// Daily price notifications (« bonnes affaires » of the wishlist + the bell thresholds), one grouped notification per user.
// Everything outside (database, network, push sending, clock) comes in through `io`, so the same code runs in the
// Supabase function and in the tests.

const TCGDEX = 'https://api.tcgdex.net/v2', SCRY = 'https://api.scryfall.com', OPAPI = 'https://optcgapi.com/api';
const UA = 'Gleamvault/1.0 (+https://aj2chart.github.io/pokefolio/)';
const RUN_GAP = 20 * 3600e3;   // the daily job runs at most once every 20 h, whoever calls it

const T = {
  fr: { one_deal: (n, p, v) => `${n} : −${p} % depuis son ajout à ta wishlist (${v})`, one_below: (n, a, v) => `${n} est passée sous ${a} (${v})`, one_above: (n, a, v) => `${n} a dépassé ${a} (${v})`,
    many: n => `${n} cartes à surveiller`, title1: 'Bonne affaire', titleA: 'Alerte de prix', more: n => `et ${n} autre${n > 1 ? 's' : ''}`,
    test_t: 'Gleamvault', test_b: 'Les notifications fonctionnent sur cet appareil ✓' },
  en: { one_deal: (n, p, v) => `${n}: −${p}% since you added it to your wishlist (${v})`, one_below: (n, a, v) => `${n} went below ${a} (${v})`, one_above: (n, a, v) => `${n} went above ${a} (${v})`,
    many: n => `${n} cards to look at`, title1: 'Good deal', titleA: 'Price alert', more: n => `and ${n} more`,
    test_t: 'Gleamvault', test_b: 'Notifications work on this device ✓' },
};
const eur = (v, lang) => new Intl.NumberFormat(lang === 'en' ? 'en-GB' : 'fr-FR', { style: 'currency', currency: 'EUR' }).format(v);
const short = s => { s = String(s || '').trim(); return s.length > 40 ? s.slice(0, 39) + '…' : s; };

function message(hits, lang) {
  const L = T[lang] || T.fr, line = h => h.kind === 'deal' ? L.one_deal(short(h.name), Math.round(-h.pct), eur(h.value, lang))
    : (h.dir === 'below' ? L.one_below : L.one_above)(short(h.name), eur(h.price, lang), eur(h.value, lang));
  if (hits.length === 1) {
    const h = hits[0];
    return { title: h.kind === 'deal' ? L.title1 : L.titleA, body: line(h), url: `./?open=${encodeURIComponent(h.uid)}#${h.wish ? 'wishlist' : 'collection'}`, tag: 'gv-prices' };
  }
  const shown = hits.slice(0, 3).map(line), rest = hits.length - shown.length;
  return { title: L.many(hits.length), body: shown.join('\n') + (rest > 0 ? '\n' + L.more(rest) : ''), url: hits.every(h => h.wish) ? './#wishlist' : './#collection', tag: 'gv-prices' };
}

// Today's prices of the cards that matter, each card fetched once whatever the number of users holding it
async function fetchDetails(keys, io) {
  const out = new Map(); let opRows = null, scryLast = 0;
  const scry = async url => { const w = scryLast + 110 - Date.now(); if (w > 0) await io.sleep(w); scryLast = Date.now(); return io.json(url, { Accept: 'application/json', 'User-Agent': UA }); };
  const queue = [...keys];
  const worker = async () => {
    while (queue.length) {
      const k = queue.shift(), i = k.indexOf(':'), lang = k.slice(0, i), id = k.slice(i + 1);
      try {
        const g = gameOf(id);
        if (g === 'pk') out.set(k, await io.json(`${TCGDEX}/${lang}/cards/${encodeURIComponent(id)}`, { 'User-Agent': UA }));
        else if (g === 'mg') {
          const c = await scry(`${SCRY}/cards/${encodeURIComponent(id.slice(3))}`);
          let pc = c;
          if (!(+c.prices?.eur > 0 || +c.prices?.eur_foil > 0) && c.lang !== 'en') { try { pc = await scry(`${SCRY}/cards/${encodeURIComponent(c.set)}/${encodeURIComponent(c.collector_number)}`); } catch (_) { } }
          out.set(k, mgPricing(c, pc));
        } else {
          if (!opRows) opRows = io.json(`${OPAPI}/allSetCards/`, { 'User-Agent': UA }).then(r => new Map((Array.isArray(r) ? r : []).map(x => [x.card_image_id, x])));
          const row = (await opRows).get(id.slice(3));
          if (row) out.set(k, opPricing(row));
        }
      } catch (_) { /* source down for this card: no notification about it today */ }
    }
  };
  await Promise.all(Array.from({ length: 4 }, worker));
  return out;
}

// Which cards cross a threshold today, for one user (collection as synced by the app)
function hitsFor(collection, details, dealPct, usdEur, todayStr) {
  const hits = [];
  for (const e of Array.isArray(collection) ? collection : []) {
    if (!e || typeof e !== 'object' || e.manualCard || typeof e.uid !== 'string') continue;
    const wish = e.status === 'wish';
    if (!wish && !e.alert) continue;
    const d = details.get(e.lang + ':' + e.cardId);
    if (!d) continue;
    const { value } = valueToday(e, d, usdEur);
    if (value == null) continue;
    if (alertHit(e, value)) hits.push({ kind: 'alert', uid: e.uid, name: e.name, value, price: e.alert.price, dir: e.alert.dir, wish });
    else if (wish) { const pct = dealDrop(e, value, todayStr); if (pct <= -dealPct) hits.push({ kind: 'deal', uid: e.uid, name: e.name, value, pct, wish }); }
  }
  return hits;
}

async function runDaily(io) {
  const now = io.now(), last = await io.getLastRun();
  if (last && now - last < RUN_GAP) return { skipped: true };
  await io.setLastRun(now);
  const subs = await io.listSubs();
  if (!subs.length) return { users: 0, sent: 0 };
  const byUser = new Map(); for (const s of subs) { if (!byUser.has(s.user_id)) byUser.set(s.user_id, []); byUser.get(s.user_id).push(s); }
  const users = [...byUser.keys()], data = await io.getCollections(users), state = await io.getStates(users);
  const keys = new Set();
  for (const u of users) for (const e of data.get(u) || []) if (e && !e.manualCard && (e.status === 'wish' || e.alert) && e.lang && e.cardId) keys.add(e.lang + ':' + e.cardId);
  const [details, usdEur] = await Promise.all([fetchDetails(keys, io), io.usdEur()]);
  const todayStr = new Date(now).toISOString().slice(0, 10);
  let sent = 0, gone = 0;
  for (const u of users) {
    const mine = byUser.get(u), pct = Math.min(25, Math.max(5, Math.max(...mine.map(s => +s.deal_pct || 5))));
    const hits = hitsFor(data.get(u), details, pct, usdEur, todayStr);
    const before = state.get(u) || {}, now_ = {};
    for (const h of hits) now_[h.uid] = h.kind;
    const fresh = hits.filter(h => before[h.uid] !== h.kind);   // notified once per crossing; a card back above the line can notify again later
    await io.setState(u, now_);
    if (!fresh.length) continue;
    for (const s of mine) {
      const st = await io.send(s, message(fresh, s.lang === 'en' ? 'en' : 'fr'));
      if (st === 404 || st === 410) { await io.deleteSub(s.endpoint); gone++; } else if (st >= 200 && st < 300) sent++;
    }
  }
  return { users: users.length, cards: keys.size, sent, gone };
}

// « Send a test » from the app: only to the devices of the signed-in user, at most once a minute
async function runTest(io, userId) {
  const subs = (await io.listSubs()).filter(s => s.user_id === userId);
  if (!subs.length) return { sent: 0, reason: 'no_device' };
  let sent = 0;
  for (const s of subs) {
    const L = T[s.lang === 'en' ? 'en' : 'fr'];
    const st = await io.send(s, { title: L.test_t, body: L.test_b, url: './#data', tag: 'gv-test' });
    if (st === 404 || st === 410) await io.deleteSub(s.endpoint); else if (st >= 200 && st < 300) sent++;
  }
  return { sent };
}

// ---- main.ts ----
// Supabase Edge Function « notify-prices » (Deno). Two uses:
//  - daily, by the scheduled job (Supabase → Integrations → Cron, 08:00 UTC): price check and notifications (runDaily);
//  - « Send a test » from the app (body {mode:'test'} + the user's session): a test notification to that user's devices.
//  - {mode:'key'}: the public sending key, for the app to subscribe (the key pair is made here on the first call and kept in
//    push_runs, a table only the server can read: no secret to copy anywhere).
// SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are provided by Supabase to every function.
// « Verify JWT » is turned off for this function: the daily run is harmless to call (it runs at most once every 20 h)
// and the test checks the caller's session itself.

const CORS = { 'Access-Control-Allow-Origin': 'https://aj2chart.github.io', 'Access-Control-Allow-Headers': 'authorization, apikey, content-type, x-client-info', 'Access-Control-Allow-Methods': 'POST, OPTIONS' };
const reply = (body: unknown, status = 200) => new Response(JSON.stringify(body), { status, headers: { ...CORS, 'Content-Type': 'application/json' } });

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') return new Response(null, { headers: CORS });
  // every failure comes back as readable JSON with the CORS headers (otherwise the browser only sees « request failed »)
  try { return await handle(req); }
  catch (e) { console.error('notify-prices:', e); return reply({ error: String((e as { message?: string })?.message || e) }, 500); }
});

// server key: the classic name, or one of the new « secret keys » Supabase may provide instead
function serverKey(env: (k: string) => string) {
  if (env('SUPABASE_SERVICE_ROLE_KEY')) return env('SUPABASE_SERVICE_ROLE_KEY');
  try { const all = JSON.parse(env('SUPABASE_SECRET_KEYS') || '{}'); const v = Object.values(all)[0]; if (typeof v === 'string') return v; } catch (_) { /* not JSON */ }
  return env('SUPABASE_SECRET_KEY');
}

async function handle(req: Request) {
  const env = (k: string) => Deno.env.get(k) || '';
  const key = serverKey(env);
  if (!env('SUPABASE_URL') || !key) return reply({ error: 'server key missing (SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY)' }, 500);
  const db = createClient(env('SUPABASE_URL'), key, { auth: { persistSession: false } });
  const must = <T>(r: { data: T; error: unknown }) => { if (r.error) throw r.error; return r.data; };
  // sending keys: made once, then always the same (changing them would cut every device's subscription)
  const probe = await db.from('push_runs').select('vapid_pub,vapid_priv').eq('id', 1).maybeSingle();
  if (probe.error) return reply({ error: 'push tables missing or not readable: run supabase/push.sql (' + probe.error.message + ')' }, 500);
  let keys = probe.data as { vapid_pub?: string; vapid_priv?: string } | null;
  if (!keys?.vapid_pub || !keys?.vapid_priv) {
    const made = await makeVapid();
    // two first calls at the same time: only the first pair is kept (update only while empty), both then read it back
    must(await db.from('push_runs').upsert({ id: 1 }, { onConflict: 'id', ignoreDuplicates: true }));
    must(await db.from('push_runs').update({ vapid_pub: made.pub, vapid_priv: made.priv }).eq('id', 1).is('vapid_pub', null));
    keys = must(await db.from('push_runs').select('vapid_pub,vapid_priv').eq('id', 1).maybeSingle()) as { vapid_pub: string; vapid_priv: string };
  }
  const vapid = { pub: keys!.vapid_pub!, subject: 'https://aj2chart.github.io/pokefolio/', key: await vapidKey(keys!.vapid_pub!, keys!.vapid_priv!) };
  const io = {
    now: () => Date.now(),
    sleep: (ms: number) => new Promise(r => setTimeout(r, ms)),
    json: async (url: string, headers: Record<string, string>) => { const r = await fetch(url, { headers }); if (!r.ok) throw new Error(String(r.status)); return r.json(); },
    usdEur: async () => { try { const j = await (await fetch('https://api.frankfurter.app/latest?from=USD&to=EUR')).json(); const r = +j?.rates?.EUR; return r > 0.3 && r < 3 ? r : 0.9; } catch (_) { return 0.9; } },
    getLastRun: async () => { const d = must(await db.from('push_runs').select('last_run').eq('id', 1).maybeSingle()) as { last_run?: string } | null; return d?.last_run ? Date.parse(d.last_run) : 0; },
    setLastRun: async (t: number) => { must(await db.from('push_runs').upsert({ id: 1, last_run: new Date(t).toISOString() })); },
    listSubs: async () => must(await db.from('push_subs').select('endpoint,user_id,p256dh,auth,deal_pct,lang')) as Array<Record<string, string>>,
    getCollections: async (ids: string[]) => { const rows = must(await db.from('user_data').select('user_id,data').in('user_id', ids)) as Array<{ user_id: string; data: { collection?: unknown[] } }>; return new Map(rows.map(r => [r.user_id, r.data?.collection || []])); },
    getStates: async (ids: string[]) => { const rows = must(await db.from('push_state').select('user_id,notified').in('user_id', ids)) as Array<{ user_id: string; notified: Record<string, string> }>; return new Map(rows.map(r => [r.user_id, r.notified || {}])); },
    setState: async (u: string, notified: Record<string, string>) => { must(await db.from('push_state').upsert({ user_id: u, notified, updated_at: new Date().toISOString() })); },
    deleteSub: async (endpoint: string) => { await db.from('push_subs').delete().eq('endpoint', endpoint); },
    send: (s: Record<string, string>, payload: unknown) => sendPush(fetch, s, payload, vapid).catch(() => 0),
  };
  {
    const body = req.method === 'POST' ? await req.json().catch(() => ({})) : {};
    if (body?.mode === 'key') return reply({ key: vapid.pub });
    if (body?.mode === 'test') {
      const jwt = (req.headers.get('Authorization') || '').replace(/^Bearer\s+/i, '');
      const { data: u } = await db.auth.getUser(jwt);
      if (!u?.user) return reply({ error: 'not signed in' }, 401);
      const st = must(await db.from('push_state').select('test_at').eq('user_id', u.user.id).maybeSingle()) as { test_at?: string } | null;
      if (st?.test_at && Date.now() - Date.parse(st.test_at) < 60e3) return reply({ error: 'wait' }, 429);
      must(await db.from('push_state').upsert({ user_id: u.user.id, test_at: new Date().toISOString() }));
      return reply(await runTest(io, u.user.id));
    }
    return reply(await runDaily(io));
  }
}
